"use client"

import React, { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function App() {
  const [theme, setTheme] = useState("light");
  const [count, setCount] = useState(0);
  const [showModal, setShowModal] = useState(false);
  const [items, setItems] = useState([]);
  const inputRef = useRef(null);

  // Effect for side operations
  useEffect(() => {
    const interval = setInterval(() => setCount((c) => c + 1), 3000);
    return () => clearInterval(interval);
  }, []);

  // Memoized calculation
  const memoizedValue = useMemo(() => count * 2, [count]);

  // Add and remove items
  const addItem = useCallback(() => {
    setItems((prev) => [...prev, { id: Date.now(), text: `Item ${prev.length + 1}` }]);
  }, []);

  const removeItem = useCallback(() => {
    setItems((prev) => prev.slice(0, -1));
  }, []);

  return (
    <div
      className={`flex flex-col items-center justify-center min-h-screen p-6 transition-colors duration-500 ${
        theme === "dark" ? "bg-gray-900 text-white" : "bg-white text-gray-900"
      }`}
    >
      {/* Header */}
      <motion.h1
        className="text-4xl font-bold mb-6"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
      >
        Complex React App
      </motion.h1>

      {/* Theme Toggle */}
      <button
        onClick={() => setTheme(theme === "light" ? "dark" : "light")}
        className="px-4 py-2 rounded-lg bg-indigo-500 text-white mb-4 shadow-md hover:bg-indigo-600"
      >
        Toggle Theme
      </button>

      {/* Counter */}
      <motion.div
        className="mb-6 text-2xl font-semibold"
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
      >
        Count: {count} | Memoized: {memoizedValue}
      </motion.div>

      {/* Input Field */}
      <div className="mb-4">
        <label className="block mb-1">Type Something:</label>
        <input
          ref={inputRef}
          className="border rounded-lg px-3 py-2 shadow-md text-gray-900"
          placeholder="Focus me!"
        />
      </div>

      {/* Buttons */}
      <div className="flex gap-4 mb-6">
        <button
          onClick={addItem}
          className="px-4 py-2 rounded-lg bg-green-500 text-white shadow-md hover:bg-green-600"
        >
          Add Item
        </button>
        <button
          onClick={removeItem}
          className="px-4 py-2 rounded-lg bg-red-500 text-white shadow-md hover:bg-red-600"
        >
          Remove Item
        </button>
        <button
          onClick={() => setShowModal(true)}
          className="px-4 py-2 rounded-lg bg-blue-500 text-white shadow-md hover:bg-blue-600"
        >
          Show Modal
        </button>
      </div>

      {/* Items List */}
      <div className="grid grid-cols-2 gap-4 w-full max-w-md">
        <AnimatePresence>
          {items.map((item) => (
            <motion.div
              key={item.id}
              className="p-4 bg-indigo-100 rounded-lg shadow-md text-center font-medium text-gray-900"
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
            >
              {item.text}
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      {/* Modal */}
      <AnimatePresence>
        {showModal && (
          <motion.div
            className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              className="bg-white text-gray-900 p-6 rounded-xl shadow-lg max-w-sm w-full"
              initial={{ scale: 0.7 }}
              animate={{ scale: 1 }}
              exit={{ scale: 0.7 }}
            >
              <h2 className="text-xl font-bold mb-4">Hello from Modal</h2>
              <p className="mb-4">This is a modal with animation and hooks.</p>
              <button
                onClick={() => setShowModal(false)}
                className="px-4 py-2 rounded-lg bg-indigo-500 text-white hover:bg-indigo-600"
              >
                Close
              </button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

